contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount == 10, "only exact ticket amount");
        require(address(this).balance >= amount, "not enough balance");

        uint beforePot = c.pot(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;
        if (beforePot != 0) {
            // pot must be zero before a first play in a fresh contract; if not, this is a violation
            assert(beforePot == 0);
            return;
        }

        c.play{value: amount}(); if (__ESBMC_reverted()) return;

        uint afterPot = c.pot(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        assert(afterBal >= afterPot);
    }

    receive() external payable {}
}

